 "content": "from collections import deque

def transform(grid):
    """Color cavities inside closed 1-shapes red (leaving each cavity's center), and halo them blue."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    zeros = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0}

    # Flood all background cells connected to the edge; any remaining zeros are enclosed cavities.
    exterior = set()
    q = deque()
    for r, c in zeros:
        if r in (0, h - 1) or c in (0, w - 1):
            exterior.add((r, c))
            q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            p = (r + dr, c + dc)
            if p in zeros and p not in exterior:
                exterior.add(p)
                q.append(p)

    cavities = zeros - exterior
    if not cavities:
        return out

    # Find cavity components. Keep their center cell(s) unpainted, color the rest red.
    cavity_components = []
    unseen = set(cavities)
    while unseen:
        start = unseen.pop()
        comp = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                p = (r + dr, c + dc)
                if p in unseen:
                    unseen.remove(p)
                    comp.add(p)
                    q.append(p)
        cavity_components.append(comp)
        rmin, rmax = min(r for r, c in comp), max(r for r, c in comp)
        cmin, cmax = min(c for r, c in comp), max(c for r, c in comp)
        center = ((rmin + rmax) // 2, (cmin + cmax) // 2)
        for r, c in comp:
            if (r, c) != center:
                out[r][c] = 3

    # Paint blue the exterior cells directly adjacent to the 1-wall of a cavity.
    for comp in cavity_components:
        walls = set()
        for r, c in comp:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                p = (r + dr, c + dc)
                if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 1:
                    walls.add(p)
