    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            top = min(y for y, _ in component)
            bottom = max(y for y, _ in component)
            left = min(x for _, x in component)
            right = max(x for _, x in component)
            zeros = {(y, x) for y in range(top, bottom + 1)
                     for x in range(left, right + 1) if grid[y][x] == 0}
            exterior = set()
            flood = []
            for y, x in zeros:
                if y in (top, bottom) or x in (left, right):
                    exterior.add((y, x))
                    flood.append((y, x))
            while flood:
                y, x = flood.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    pos = (y + dy, x + dx)
                    if pos in zeros and pos not in exterior:
                        exterior.add(pos)
                        flood.append(pos)
            holes = zeros - exterior
            if not holes:
                continue
            # An enclosed shape is framed one cell outside its bounding box.
            for y in range(max(0, top - 1), min(h, bottom + 2)):
                for x in range(max(0, left - 1), min(w, right + 2)):
                    top_edge = top - 1 if top > 0 else 0
                    left_edge = left - 1 if left > 0 else 0
                    if (y in (top_edge, bottom + 1) or x in (left_edge, right + 1)) and out[y][x] == 0:
                        out[y][x] = 2
            # Fill the interior except for its central pixel.
            center = ((top + bottom + 1) // 2, (left + right) // 2)
            for y, x in holes:
                if (y, x) != center:
                    out[y][x] = 3
    return out
