 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            seen.add((r, c))
            q = deque([(r, c)])
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1,0), (-1,0), (0,1), (0,-1)):
                    p = (y + dy, x + dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 1 and p not in seen:
                        seen.add(p)
                        q.append(p)
            top = min(y for y, x in comp)
            bottom = max(y for y, x in comp)
            left = min(x for y, x in comp)
            right = max(x for y, x in comp)
            zeros = {(y, x) for y in range(top, bottom + 1)
                     for x in range(left, right + 1) if grid[y][x] == 0}
            exterior = set()
            flood = []
            for y, x in zeros:
                if y in (top, bottom) or x in (left, right):
                    exterior.add((y, x))
                    flood.append((y, x))
            while flood:
                y, x = flood.pop()
                for dy, dx in ((1,0), (-1,0), (0,1), (0,-1)):
                    p = (y + dy, x + dx)
                    if p in zeros and p not in exterior:
                        exterior.add(p)
                        flood.append(p)
            holes = zeros - exterior
            if not holes:
                continue
            center = ((top + bottom + 1) // 2, (left + right + 1) // 2)
            for y, x in holes:
                if (y, x) != center:
                    out[y][x] = 3
            top_edge = max(0, top - 1)
            left_edge = max(0, left - 1)
            for y in range(max(0, top - 1), min(h, bottom + 2)):
                for x in range(max(0, left - 1), min(w, right + 2)):
                    if (y in (top_edge, bottom + 1) or x in (left_edge, right + 1)) and out[y][x] == 0:
                        out[y][x] = 2
    return out
