def transform(grid):
    """Fill each globally enclosed zero cavity with 3 except its central cell;
    add an 8-neighbor blue halo around the 1-component enclosing it.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    zeros = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0}
    exterior = set()
    q = deque()
    for r, c in zeros:
        if r in (0, h - 1) or c in (0, w - 1):
            exterior.add((r, c))
            q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            p = (r + dr, c + dc)
            if p in zeros and p not in exterior:
                exterior.add(p)
                q.append(p)

    enclosed = zeros - exterior
    seen = set()
    for start in enclosed:
        if start in seen:
            continue
        cavity = {start}
        seen.add(start)
        q.append(start)
        while q:
            r, c = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                p = (r + dr, c + dc)
                if p in enclosed and p not in seen:
                    seen.add(p)
                    cavity.add(p)
                    q.append(p)

        top = min(r for r, _ in cavity)
        bottom = max(r for r, _ in cavity)
        left = min(c for _, c in cavity)
        right = max(c for _, c in cavity)
        center = ((top + bottom) // 2, (left + right) // 2)
        for r, c in cavity:
